Lemma evq_drain : forall {R} RP ga G st (k : astate -> AM R) extra,
  LW st -> QOK G st -> 0 <= extra ->
  (forall st', LW st' -> QOK G st' -> PHI st' <= PHI st -> evq RP ga G (PHI st' + extra) (k st')) ->
  evq RP ga G (PHI st + extra) (drain st k).
